"""Guided business workflows: visible source, checks, human review and assumptions."""
import html,json
from pathlib import Path
W=json.loads((Path(__file__).parent/'workflow.json').read_text())
def e(v):return html.escape(str(v),quote=True)
def icon(name):
 paths={'mail':'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="m4 7 8 6 8-6"/>','code':'<path d="m8 6-6 6 6 6m8-12 6 6-6 6m-3-15-2 18"/>','flow':'<rect x="8" y="2" width="8" height="6" rx="1"/><rect x="2" y="16" width="7" height="6" rx="1"/><rect x="15" y="16" width="7" height="6" rx="1"/><path d="M12 8v4H5v4m7-4h7v4"/>','chart':'<path d="M3 3v18h18M7 16l4-5 4 2 6-8"/>','screen':'<rect x="2" y="3" width="20" height="15" rx="2"/><path d="M8 22h8m-4-4v4M2 8h20"/>','check':'<path d="m5 12 4 4L19 6"/>','shield':'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6z"/><path d="m8 11 3 3 5-5"/>','document':'<path d="M14 2H5v20h14V7zM14 2v5h5M8 12h8M8 16h6"/>','arrow':'<path d="M4 12h16m-6-6 6 6-6 6"/>','people':'<circle cx="9" cy="7" r="3"/><path d="M3 21v-4a6 6 0 0 1 12 0v4m2-17a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 4v4"/>'}
 return '<svg class="semantic-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths[name]+'</svg>'
def dashboard(t,identifier='hero'):
 s=t['workflow'];c=s['cases'][0];pre='flow-'+identifier
 choices=''.join(f'<button type="button" data-flow-case="{i}" aria-pressed="{str(i==0).lower()}">{e(v["label"])}</button>' for i,v in enumerate(s['cases']))
 steps=''.join(f'<li data-flow-step="{i}">{icon(name)}<span>{e(v)}</span></li>' for i,(v,name) in enumerate(zip(s['steps'],['document','shield','flow'])))
 return f'''<div class="workflow-app" data-workflow="{e(identifier)}"><header class="workflow-header"><span class="workflow-brand">{icon('flow')} NOVALIS <b>FLOW</b></span><span class="workflow-label">{e(s['label'])}</span></header><div class="workflow-switch" role="group" aria-label="{e(s['choose'])}">{choices}</div><div class="workflow-canvas"><div class="flow-source"><div class="flow-source-top">{icon('mail')}<span data-flow-source>{e(c['source'])}</span><span class="flow-source-badge">{e(s['incoming'])}</span></div><p data-flow-message>{e(c['message'])}</p></div><ol class="flow-steps">{steps}</ol><div class="flow-ready"><span class="flow-orbit" aria-hidden="true">{icon('arrow')}</span><p>{e(s['promise'])}</p></div><button class="flow-run" type="button" data-flow-run>{e(s['run'])}{icon('arrow')}</button><div class="flow-result" data-flow-result hidden><div class="flow-result-title">{icon('check')}<strong data-flow-result-title>{e(s['result_title'])}</strong><span>{e(s['review_badge'])}</span></div><dl data-flow-fields></dl><div class="flow-draft"><span>{e(s['draft'])}</span><p data-flow-draft></p></div><p class="flow-check" data-flow-check></p></div><div class="flow-status" role="status" data-flow-status></div></div><footer class="workflow-footer"><button type="button" data-flow-exception aria-pressed="false">{icon('shield')}{e(s['exception'])}</button><span>{e(s['local'])}</span></footer><details class="flow-impact"><summary>{e(s['impact_title'])}<span>+</span></summary><p>{e(s['impact_copy'])}</p><div class="flow-assumptions"><label for="{pre}-volume">{e(s['volume'])}<input id="{pre}-volume" data-flow-volume type="number" min="1" max="10000" value="100" inputmode="numeric"></label><label for="{pre}-manual">{e(s['manual'])}<input id="{pre}-manual" data-flow-manual type="number" min="1" max="120" value="6" inputmode="numeric"></label><label for="{pre}-review">{e(s['review'])}<input id="{pre}-review" data-flow-review type="number" min="1" max="120" value="2" inputmode="numeric"></label></div><p class="flow-estimate" data-flow-estimate role="status"></p><small>{e(s['assumption_note'])}</small></details><noscript><p>{e(s['noscript'])}</p></noscript></div>'''
def hero(t,prefix):
 from launch import hero as launch_hero
 return launch_hero(t,prefix)

def previous_hero(t,prefix):
 s=t['workflow']
 return f'''<section class="engineering-hero flow-hero shell" aria-labelledby="hero-title"><div class="engineering-hero-copy"><p class="eyebrow"><span class="status-dot" aria-hidden="true"></span>{e(t['eyebrow'])}</p><h1 id="hero-title"><span>{e(t['hero'][0])}</span><span class="hero-reveal">{e(t['hero'][1])}</span></h1><p class="engineering-intro">{e(s['intro'])}</p><div class="hero-actions"><a class="button" href="#contact">{e(t['cta'])}{icon('arrow')}</a><a class="flow-explore" href="#solutions">{e(t['explore'])} ↓</a></div><p class="small-copy">{e(t['hour'])}</p></div><div class="flow-hero-demo"><p class="flow-caption"><span>{e(s['caption'])}</span><b>{e(s['try'])} ↓</b></p>{dashboard(t)}</div><div class="flow-hero-bottom"><p>{e(s['bottom'])}</p><a href="#saas">{e(s['os_link'])} {icon('arrow')}</a></div></section>'''
